css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; }
.loader span { position: absolute; width: 13%; height: 17%; border-radius: 50%; background: radial-gradient(circle at 36% 32%, var(--accent-2), var(--accent)); transform: scale(0); animation: tree-node calc(var(--loader-speed) * 3) ease-out infinite; }
.loader span::before { content: ''; position: absolute; left: 42%; bottom: 96%; width: calc(var(--loader-size) * .016); height: calc(var(--loader-size) * .19); border-radius: 2px; background: color-mix(in srgb, var(--accent) 45%, transparent); transform-origin: 50% 100%; transform: rotate(var(--tilt, 0deg)); }
.loader span:nth-of-type(1) { left: 43.5%; top: 2%; }
.loader span:nth-of-type(1)::before { display: none; }
.loader span:nth-of-type(2) { left: 21%; top: 40%; --tilt: 38deg; animation-delay: calc(var(--loader-speed) * .28); }
.loader span:nth-of-type(3) { left: 66%; top: 40%; --tilt: -38deg; animation-delay: calc(var(--loader-speed) * .28); }
.loader span:nth-of-type(4) { left: 6%; top: 78%; --tilt: 30deg; animation-delay: calc(var(--loader-speed) * .56); }
.loader span:nth-of-type(5) { left: 32%; top: 78%; --tilt: -30deg; animation-delay: calc(var(--loader-speed) * .56); }
.loader span:nth-of-type(6) { left: 55%; top: 78%; --tilt: 30deg; animation-delay: calc(var(--loader-speed) * .84); }
.loader span:nth-of-type(7) { left: 81%; top: 78%; --tilt: -30deg; animation-delay: calc(var(--loader-speed) * .84); }
@keyframes tree-node { 0%, 4% { transform: scale(0); opacity: 0; } 22%, 72% { transform: scale(1); opacity: 1; } 90%, 100% { transform: scale(0); opacity: 0; } }
